import { readFile, writeFile, mkdir } from "node:fs/promises";
import { resolve } from "node:path";
const source = resolve(
  process.argv.find((arg) => arg.startsWith("--source="))?.slice(9) ??
    "../contracts/bindings/index.ts",
);
const target = resolve("src/lib/generated/index.ts");
const content = await readFile(source, "utf8");
if (
  !content.startsWith(
    "// Generated by cargo run --bin export-contracts. DO NOT EDIT.",
  )
)
  throw Error("Not the admitted ts-rs export");
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== content)
    throw Error("Generated DTO drift; run sync-contracts");
  console.log("Generated DTOs match backend export");
} else {
  await mkdir(resolve("src/lib/generated"), { recursive: true });
  await writeFile(target, content);
  console.log(`Copied actual Rust ts-rs export from ${source}`);
}
